package com.gymmind.booking.domain.model; import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; @Entity @Table(name="course_booking",uniqueConstraints=@UniqueConstraint(name="uk_booking_tenant_member_course",columnNames={"tenant_id","member_id","course_id"})) public class Booking extends TenantScopedEntity{@Column(name="member_id",nullable=false)Long memberId;@Column(name="course_id",nullable=false)Long courseId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)BookingStatus status=BookingStatus.CONFIRMED;protected Booking(){}private Booking(Long t,Long m,Long c){super(t);memberId=m;courseId=c;}public static Booking create(Long t,Long m,Long c){return new Booking(t,m,c);}public void cancel(){status=BookingStatus.CANCELLED;}public void complete(){status=BookingStatus.COMPLETED;}public Long getMemberId(){return memberId;}public Long getCourseId(){return courseId;}public BookingStatus getStatus(){return status;}}
